int n;
vector<long long> values;
vector<char> deleted_node, used;
vector<int> order;

inline bool has_edge(int u, int v) {
    return u != v && (values[u] & values[v]) == values[u];
}

void top_sort(int u) {
    used[u] = true;
    for (int v = 0; v < n; ++v) {
        if (!used[v] && !deleted_node[v] && has_edge(u, v)) {
            top_sort(v);
        }
    }
    order.push_back(u);
}

long long get_sum(int u, const vector<long long>& b) {
    long long sum = b[u];
    used[u] = true;

    for (int v = 0; v < n; ++v) {
        if (!used[v] && !deleted_node[v] && has_edge(u, v)) {
            sum += get_sum(v, b);
        }
    }
    return sum;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;

    values.resize(n);
    vector<long long> b(n);

    for (long long& x : values) cin >> x;
    for (long long& x : b) cin >> x;

    vector<int> child_count(n, 0);

    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            if (has_edge(i, j)) ++child_count[i];
            if (has_edge(j, i)) ++child_count[j];
        }
    }

